// Author: MiYu. Persist local preferences separately from the original game resources.
#include "game_preferences.h"
#include <algorithm>
#include <array>
#include <atomic>

namespace war3 {
namespace {
constexpr std::array<std::uint8_t,8> cameraMagic{'W','3','C','A','M',1,0,0};
constexpr std::array<std::uint8_t,8> cameraMagicV2{'W','3','C','A','M',2,0,0};
constexpr std::array<std::uint8_t,8> cameraMagicV3{'W','3','C','A','M',3,0,0};
constexpr std::array<std::uint8_t,8> cameraMagicV4{'W','3','C','A','M',4,0,0};
constexpr std::array<std::uint8_t,8> cameraMagicV5{'W','3','C','A','M',5,0,0};
constexpr std::array<std::uint8_t,8> cameraMagicV6{'W','3','C','A','M',6,0,0};
constexpr std::array<std::uint8_t,8> audioMagic{'W','3','A','U','D',1,0,0};
constexpr std::array<std::uint8_t,8> audioMagicV2{'W','3','A','U','D',2,0,0};
constexpr std::array<std::uint8_t,8> audioMagicV3{'W','3','A','U','D',3,0,0};
constexpr std::array<std::uint8_t,8> videoMagic{'W','3','V','I','D',1,0,0};
constexpr std::array<std::uint8_t,8> videoMagicV2{'W','3','V','I','D',2,0,0};
constexpr std::array<std::uint8_t,8> videoMagicV3{'W','3','V','I','D',3,0,0};
std::atomic<unsigned> serial=0;
fs::path path(const fs::path& root,const wchar_t* name){validateWar3UserDirectory(root);return war3UserDirectory()/L"Settings"/name;}
std::optional<Bytes> read(const fs::path& file,std::span<const std::uint8_t> magic,size_t size){
    std::error_code error;if(!fs::exists(file,error)){if(error)throw std::runtime_error("Cannot inspect preferences");return {};}auto length=fs::file_size(file,error);if(error || length!=size)throw std::runtime_error("Unsupported preferences size");std::ifstream input(file,std::ios::binary);Bytes bytes(size);if(!input || !input.read(reinterpret_cast<char*>(bytes.data()),std::streamsize(bytes.size())) || input.peek()!=std::char_traits<char>::eof())throw std::runtime_error("Cannot read preferences");if(!std::equal(magic.begin(),magic.end(),bytes.begin()))throw std::runtime_error("Unsupported preferences format");return bytes;
}
void publish(const fs::path& file,std::span<const std::uint8_t> bytes){
    fs::create_directories(file.parent_path());fs::path temp;HANDLE handle=INVALID_HANDLE_VALUE;DWORD createError=ERROR_FILE_EXISTS;for(unsigned attempt=0;attempt<32 && handle==INVALID_HANDLE_VALUE;++attempt){temp=file;temp+=L"."+std::to_wstring(GetCurrentProcessId())+L"."+std::to_wstring(++serial)+L".tmp";handle=CreateFileW(temp.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(handle==INVALID_HANDLE_VALUE){createError=GetLastError();if(createError!=ERROR_FILE_EXISTS && createError!=ERROR_ALREADY_EXISTS)break;}}if(handle==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot create preferences: "+winError(createError));DWORD written=0;bool good=WriteFile(handle,bytes.data(),DWORD(bytes.size()),&written,nullptr) && written==bytes.size() && FlushFileBuffers(handle);DWORD error=good?ERROR_SUCCESS:GetLastError();CloseHandle(handle);if(!good){DeleteFileW(temp.c_str());throw std::runtime_error("Cannot write preferences: "+winError(error));}if(!MoveFileExW(temp.c_str(),file.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){error=GetLastError();DeleteFileW(temp.c_str());throw std::runtime_error("Cannot publish preferences: "+winError(error));}
}
}
GameCameraPreferences loadCameraPreferences(const fs::path& root){
    auto file=path(root,L"camera.bin");std::error_code error;if(!fs::exists(file,error)){if(error)throw std::runtime_error("Cannot inspect camera preferences");return {};}auto length=fs::file_size(file,error);if(error)throw std::runtime_error("Cannot inspect camera preference size");bool legacy=length==cameraMagic.size()+1,version2=length==cameraMagicV2.size()+3,version3=length==cameraMagicV3.size()+4,version4=length==cameraMagicV4.size()+5,version5=length==cameraMagicV5.size()+6,version6=length==cameraMagicV6.size()+7;if(!legacy && !version2 && !version3 && !version4 && !version5 && !version6)throw std::runtime_error("Unsupported camera preferences size");auto bytes=legacy?read(file,cameraMagic,cameraMagic.size()+1):version2?read(file,cameraMagicV2,cameraMagicV2.size()+3):version3?read(file,cameraMagicV3,cameraMagicV3.size()+4):version4?read(file,cameraMagicV4,cameraMagicV4.size()+5):version5?read(file,cameraMagicV5,cameraMagicV5.size()+6):read(file,cameraMagicV6,cameraMagicV6.size()+7);if(!bytes)throw std::runtime_error("Camera preferences changed during read");auto at=cameraMagic.size();if((*bytes)[at]>1 || (!legacy && ((*bytes)[at+1]>100 || (*bytes)[at+2]>100)) || ((version3 || version4 || version5 || version6) && (*bytes)[at+3]>1) || ((version4 || version5 || version6) && (*bytes)[at+4]>1) || ((version5 || version6) && (*bytes)[at+5]>1) || (version6 && (*bytes)[at+6]>1))throw std::runtime_error("Invalid camera preferences");return {(*bytes)[at]!=0,legacy?50u:unsigned((*bytes)[at+1]),legacy?50u:unsigned((*bytes)[at+2]),(version3 || version4 || version5 || version6) && (*bytes)[at+3]!=0,!(version4 || version5 || version6) || (*bytes)[at+4]!=0,!(version5 || version6) || (*bytes)[at+5]!=0,version6 && (*bytes)[at+6]!=0};
}
void saveCameraPreferences(const fs::path& root,const GameCameraPreferences& value){if(value.mouseSpeed>100 || value.keySpeed>100)throw std::runtime_error("Invalid camera preference speed");loadCameraPreferences(root);auto file=path(root,L"camera.bin");Bytes bytes(cameraMagicV6.begin(),cameraMagicV6.end());bytes.insert(bytes.end(),{std::uint8_t(value.edgeScroll),std::uint8_t(value.mouseSpeed),std::uint8_t(value.keySpeed),std::uint8_t(value.healthBars),std::uint8_t(value.enhancedTooltips),std::uint8_t(value.formationMovement),std::uint8_t(value.subgroupModifier)});publish(file,bytes);}
GameAudioPreferences loadAudioPreferences(const fs::path& root){auto file=path(root,L"audio.bin");std::error_code error;if(!fs::exists(file,error)){if(error)throw std::runtime_error("Cannot inspect audio preferences");return {};}auto length=fs::file_size(file,error);if(error)throw std::runtime_error("Cannot inspect audio preference size");bool legacy=length==audioMagic.size()+4,version2=length==audioMagicV2.size()+5,version3=length==audioMagicV3.size()+8;if(!legacy && !version2 && !version3)throw std::runtime_error("Unsupported audio preferences size");auto bytes=legacy?read(file,audioMagic,audioMagic.size()+4):version2?read(file,audioMagicV2,audioMagicV2.size()+5):read(file,audioMagicV3,audioMagicV3.size()+8);if(!bytes)throw std::runtime_error("Audio preferences changed during read");auto at=audioMagic.size();if((*bytes)[at]>1 || (*bytes)[at+1]>1 || (*bytes)[at+2]>100 || (*bytes)[at+3]>100 || ((version2 || version3) && (*bytes)[at+4]>1) || (version3 && ((*bytes)[at+5]>1 || (*bytes)[at+6]>1 || (*bytes)[at+7]>1)))throw std::runtime_error("Invalid audio preferences");return {(*bytes)[at]!=0,(*bytes)[at+1]!=0,(*bytes)[at+2],(*bytes)[at+3],legacy || (*bytes)[at+4]!=0,!version3 || (*bytes)[at+5]!=0,!version3 || (*bytes)[at+6]!=0,!version3 || (*bytes)[at+7]!=0};}
void saveAudioPreferences(const fs::path& root,const GameAudioPreferences& value){if(value.soundVolume>100 || value.musicVolume>100)throw std::runtime_error("Invalid audio preference volume");loadAudioPreferences(root);auto file=path(root,L"audio.bin");Bytes bytes(audioMagicV3.begin(),audioMagicV3.end());bytes.insert(bytes.end(),{std::uint8_t(value.sound),std::uint8_t(value.music),std::uint8_t(value.soundVolume),std::uint8_t(value.musicVolume),std::uint8_t(value.subtitles),std::uint8_t(value.ambient),std::uint8_t(value.movement),std::uint8_t(value.unitSounds)});publish(file,bytes);}
GameVideoPreferences loadVideoPreferences(const fs::path& root){auto file=path(root,L"video.bin");std::error_code error;if(!fs::exists(file,error)){if(error)throw std::runtime_error("Cannot inspect video preferences");return {};}auto length=fs::file_size(file,error);if(error)throw std::runtime_error("Cannot inspect video preference size");bool legacy=length==videoMagic.size()+1,version2=length==videoMagicV2.size()+2,version3=length==videoMagicV3.size()+3;if(!legacy && !version2 && !version3)throw std::runtime_error("Unsupported video preferences size");auto bytes=legacy?read(file,videoMagic,videoMagic.size()+1):version2?read(file,videoMagicV2,videoMagicV2.size()+2):read(file,videoMagicV3,videoMagicV3.size()+3);if(!bytes)throw std::runtime_error("Video preferences changed during read");auto at=videoMagic.size();if((*bytes)[at]>2 || ((version2 || version3) && (*bytes)[at+1]>1) || (version3 && (*bytes)[at+2]>2))throw std::runtime_error("Invalid video preferences");return {(*bytes)[at],legacy || (*bytes)[at+1]!=0,version3?unsigned((*bytes)[at+2]):2u};}
void saveVideoPreferences(const fs::path& root,const GameVideoPreferences& value){if(value.particleDetail>2 || value.shadowDetail>2)throw std::runtime_error("Invalid video detail");loadVideoPreferences(root);Bytes bytes(videoMagicV3.begin(),videoMagicV3.end());bytes.insert(bytes.end(),{std::uint8_t(value.particleDetail),std::uint8_t(value.occlusion),std::uint8_t(value.shadowDetail)});publish(path(root,L"video.bin"),bytes);}
}
